export async function verifyNativeCompanyPartyReports({db,profile,revision,secret}){
 const keys=['JWT_SECRET','MWS_STORE_LIFECYCLE_PROFILE','RENDER_GIT_COMMIT','BACKUP_MONITOR_SECRET'],saved=Object.fromEntries(keys.map(k=>[k,process.env[k]]));Object.assign(process.env,{JWT_SECRET:'isolated-native-company-party-reports-secret',MWS_STORE_LIFECYCLE_PROFILE:`BACKOFFICE_COMPANY_${profile}_V1`,RENDER_GIT_COMMIT:revision,BACKUP_MONITOR_SECRET:secret});
 const mutate=(sql,...values)=>db.$transaction(async tx=>{await tx.$queryRawUnsafe("SELECT set_config('mws.lifecycle_generations',$1,true)",JSON.stringify({selected:'7',sibling:'0',foreign:'0'}));return tx.$executeRawUnsafe(sql,...values)});
 const active={};for(const table of ['Supplier','Customer'])active[table]=(await db.$queryRawUnsafe(`SELECT "active" FROM "${table}" WHERE "id"=$1`,table+'-company'))[0].active;
 let server;
 try{
  for(const module of ['INVENTORY','POS','CORE'])await mutate('UPDATE "CompanyModule" SET "active"=true WHERE "companyId"=\'company\' AND "moduleKey"=$1',module);
  for(const table of ['Supplier','Customer'])await mutate(`UPDATE "${table}" SET "active"=false WHERE "id"=$1`,table+'-company');
  for(const {table,row}of nativeCompanyPartyReportSeedPlan()){const entries=Object.entries(row);await mutate(`INSERT INTO "${table}"(${entries.map(([k])=>'"'+k+'"').join(',')}) VALUES(${entries.map((_,i)=>'$'+(i+1)).join(',')})`,...entries.map(([,v])=>v))}
  const owner={id:'company-owner',companyId:'company',role:'OWNER',tokenType:'BACKOFFICE_USER',sessionId:'company-owner-session',sessionVersion:0},reports=['reports-supplier-invoices.read','reports-supplier-payments.read','reports-supplier-purchases.read','reports-customer-turnover.read'],caps=['suppliers.read','customers.read',...reports];
  for(const companyCapabilities of [[reports[0]],[reports[3]]])await assert.rejects(createStaffAccount(db,owner,{username:'rejected.party.native',fullName:'Rejected missing parent',pin:'987654',grants:[],companyCapabilities}),{name:'ZodError'});
  const created=await createStaffAccount(db,owner,{username:'company.party.reports.native',fullName:'Company Party Reports Native',pin:'987654',grants:[],companyCapabilities:caps});assert.deepEqual(new Set((await db.$queryRawUnsafe('SELECT "companyCapabilities" FROM "BackofficeStaffAccount" WHERE "userId"=$1',created.id))[0].companyCapabilities),new Set(caps));assert.equal((await db.$queryRawUnsafe('SELECT 1 FROM "BackofficeStaffGrant" WHERE "userId"=$1',created.id)).length,0);await mutate('INSERT INTO "UserSession"("id","userId","expiresAt") VALUES(\'party36-session\',$1,NOW()+INTERVAL \'1 hour\')',created.id);
  let afterRead=null;const readDb=new Proxy(db,{get(target,key){if(['$executeRaw','$executeRawUnsafe','$transaction'].includes(key))return()=>assert.fail('party report attempted writer/bootstrap');const value=target[key];if(key==='$queryRaw')return async(...args)=>{const sql=args[0].join('?');assert.doesNotMatch(sql,/\b(?:INSERT|UPDATE|DELETE|CREATE|ALTER|FOR UPDATE)\b/);const rows=await value.apply(target,args);if(afterRead&&/FROM "(?:PurchaseDocument|StoreTransaction|Sale)"/.test(sql)){const action=afterRead;afterRead=null;await action()}return rows};return typeof value==='function'?value.bind(target):value}});
  const source=await readFile(new URL('../../src/middleware/auth.js',import.meta.url),'utf8'),auth=new Function('prisma','jwt','assertCustomerDemoRuntimeClosed','enforceBackofficeStaff',source.slice(source.indexOf('export async function auth(')).replace('export async function auth','async function auth')+';return auth;')(readDb,jwt,assertCustomerDemoRuntimeClosed,enforceBackofficeStaff);
  const app=express();app.use(express.json());const index=await readFile(new URL('../../src/index.js',import.meta.url),'utf8'),start=index.indexOf('// Exact company reads precede'),end=index.indexOf('app.use("/api/management/vat-departments"',start);assert.ok(start>0&&end>start);new Function('app','auth','readStaffCompanyDirectory','readStaffStoreReport','prisma',index.slice(start,end))(app,auth,readStaffCompanyDirectory,()=>assert.fail('company party reports cannot derive Store authority'),readDb);app.use(auth);app.use((_req,res)=>res.status(404).json({code:'UNEXPECTED_FALLTHROUGH'}));app.use((e,_req,res,_next)=>res.status(e.status||500).json({code:e.code}));server=app.listen(0,'127.0.0.1');await new Promise(resolve=>server.once('listening',resolve));
  const token=jwt.sign({id:created.id,companyId:'company',role:'EMPLOYEE',tokenType:'BACKOFFICE_USER',staffAccess:true,sessionVersion:0,sessionId:'party36-session'},process.env.JWT_SECRET),range='from=2026-11-11&to=2026-11-11';
  const get=async(path,headers={})=>{const r=await fetch(`http://127.0.0.1:${server.address().port}${path}`,{headers:{authorization:'Bearer '+token,'x-backoffice-company-id':'company',...headers}});return {status:r.status,body:await r.json()}};
  const paths=['/api/supplier-control/reports/invoices','/api/supplier-control/reports/payments','/api/supplier-control/reports/purchases','/api/customer-control/turnover'],results=[];
  for(const path of paths){const r=await get(path+'?'+range);assert.equal(r.status,200,JSON.stringify({path,...r}));assert.equal(r.body.scope,'COMPANY');assert.doesNotMatch(JSON.stringify(r.body),/PARTY36_PRIVATE_ATTACHMENT|PARTY36_PRIVATE_CHECKSUM/);results.push(r.body)}
  const [invoices,payments,purchases,turnover]=results;
  assert.equal(invoices.count,5);assert.equal(invoices.summary.gross,2148);assert.equal(invoices.window.kind,'NATIVE_WINDOW');const badInvoice=invoices.items.find(r=>r.id==='party36-invoice-bad-reference');assert.equal(badInvoice.supplierId,null);assert.equal(badInvoice.supplierName,null);assert.equal(badInvoice.supplierCategory,null);assert.equal(invoices.items.find(r=>r.id==='party36-invoice-credit').totalGross,-30);assert.ok(invoices.items.every(r=>!Object.hasOwn(r,'imageRef')));
  assert.equal(payments.count,5);assert.deepEqual(payments.summary,{count:5,total:22,reversed:1});assert.equal(payments.items.find(r=>r.id==='party36-payment-zero').amount,0);assert.equal(payments.items.find(r=>r.id==='party36-payment-bad-reference').supplierId,null);assert.equal(payments.items.find(r=>r.id==='party36-payment-bad-reference').taxId,null);assert.ok(payments.items.every(r=>r.attachmentFilename==='native-proof.pdf'&&!Object.hasOwn(r,'attachmentData')));
  assert.equal(purchases.count,2);assert.deepEqual(purchases.summary,{documents:3,net:75,vat:15,gross:90});assert.equal(purchases.basis,'APPROVED_DOCUMENT_AMOUNTS');assert.equal(purchases.window.kind,'COMPLETE_FILTERED_GROUPS');const zero=await get(paths[2]+'?'+range+'&supplierId=party36-zero-supplier');assert.equal(zero.status,200);assert.equal(zero.body.summary.gross,0);assert.equal(zero.body.items[0].percentOfTotal,null);
  assert.equal(turnover.count,1);assert.deepEqual(turnover.summary,{customers:1,visits:3,turnover:135,discount:9,returns:15,reversalCount:2});assert.equal(turnover.items[0].subtotal,126);assert.equal(turnover.reversalAware,true);assert.equal(turnover.window.kind,'COMPLETE_FILTERED_GROUPS');
  assert.equal((await get(paths[0]+'?'+range+'&supplierId=Supplier-company')).status,200,'inactive owned supplier is a valid native filter');assert.equal((await get(paths[3]+'?'+range+'&customerId=Customer-company')).status,200,'inactive owned customer is a valid native filter');for(const [path,key,id]of [[paths[0],'supplierId','Supplier-foreign'],[paths[3],'customerId','Customer-foreign']])assert.equal((await get(path+'?'+range+'&'+key+'='+id)).status,404);
  for(const path of [paths[2]+'?'+range+'&q=x',paths[3]+'?'+range+'&storeId=selected',paths[0]+'?from=2026-02-30&to=2026-03-01',paths[1]+'?'+range+'&supplierId=Supplier-company&supplierId=Supplier-foreign'])assert.ok([400,403].includes((await get(path)).status));assert.equal((await get(paths[0]+'?'+range,{'x-backoffice-store-id':'selected'})).status,403);assert.equal((await get('/api/transactions/party36-payment-own/attachment')).status,403);
  for(const module of ['INVENTORY','POS','CORE']){await mutate('UPDATE "CompanyModule" SET "active"=false WHERE "companyId"=\'company\' AND "moduleKey"=$1',module);if(module==='INVENTORY'){for(const path of paths.slice(0,3))assert.equal((await get(path+'?'+range)).status,403);assert.equal((await get(paths[3]+'?'+range)).status,200)}else{assert.equal((await get(paths[3]+'?'+range)).status,403);assert.equal((await get(paths[0]+'?'+range)).status,200)}await mutate('UPDATE "CompanyModule" SET "active"=true WHERE "companyId"=\'company\' AND "moduleKey"=$1',module)}
  afterRead=()=>mutate('UPDATE "CompanyModule" SET "active"=false WHERE "companyId"=\'company\' AND "moduleKey"=\'POS\'');assert.equal((await get(paths[3]+'?'+range)).status,403,'fresh parent-directory module check withholds already-read turnover');await mutate('UPDATE "CompanyModule" SET "active"=true WHERE "companyId"=\'company\' AND "moduleKey"=\'POS\'');afterRead=()=>mutate('UPDATE "BackofficeStaffAccount" SET "revision"="revision"+1 WHERE "userId"=$1',created.id);assert.equal((await get(paths[0]+'?'+range)).status,403);afterRead=()=>mutate('UPDATE "BackofficeStaffAccount" SET "companyCapabilities"=\'[]\'::jsonb WHERE "userId"=$1',created.id);assert.equal((await get(paths[1]+'?'+range)).status,403);
 }finally{if(server){server.closeAllConnections();await new Promise(resolve=>server.close(resolve))}try{for(const table of ['Supplier','Customer'])await mutate(`UPDATE "${table}" SET "active"=$1 WHERE "id"=$2`,active[table],table+'-company')}finally{for(const key of keys){if(saved[key]===undefined)delete process.env[key];else process.env[key]=saved[key]}}}
}
